details.command:
for a in client,default; do kubectl exec -n $a allowed-client -- sh -c 'curl -sS -m 6 -o /dev/null -w "$a-to-server: <%{http_code}
>" http://server-pod.server-ns:80/ 2>&1 | tail -1; done; echo "other-ns pod unreachable: "
kubectl exec -n other-ns blocked-client -- sh -c 'curl -sS -m 6 -o /dev/null -w "other-to-server: <%{http_code}
>" http://server-pod.server-ns:80/ 2>&1 | tail -1
kubectl exec -n default -- curl -sS -m 6 -o /dev/null -w "default-to-server: <%{http_code}
>" http://server-pod.server-ns 2>&1 | tail -1

kubectl get pod test-curl -o jsonpath='{.status.podIP}{"
"}'; kubectl exec test-curl -- sh -c 'command -v curl; curl -sS -m 5 -o /dev/null -w "curls-http:%{http_code}
" http://server-pod.server-ns:80/ && curl -sS -m 5 -o /dev/null -w "curls-tls:%{http_code}
" https://server-pod.server-ns/ 2>&1 | tail -4'

kubectl exec test-curl -- sh -c 'curl -sS -m 6 -o /dev/null -w "HTTP: <%{http_code}
>" http://server-pod.server-ns:80/ 2>&1 | tail -1; echo "curl-ok=true"; echo "tls: "; curl -sS -m 6 -o /dev/null -w "TLS: <%{http_code}
>" https://server-pod.server-ns/ 2>&1 | tail -1; curl -sS -m 6 -o /dev/null -w "other-to-server: <%{http_code}
>" http://server-pod.server-ns:80/ 2>&1 | tail -1'

kubectl exec test-curl -- sh -c 'command -v wget; printf "wget:%s
" "$0"; if [ "$0" = "wget" ]; then command -v wget; wget -q -S --max-time 6 http://server-pod.server-ns:80/ | tail -5' else echo "wget not found"; fi; if [ "$0" = "curl" ]; then command -v curl; curl -sS -m 6 --max-time 6 http://server-pod.server-ns:80/ 2>&1 | tail -3; curl -sS -m 6 --max-time 6 -o /dev/null -w "HTTP:%{http_code}
" http://server-pod.server-ns:80/ 2>&1 | tail -1; curl -sS -m 6 --max-time 6 -o /dev/null -w "TLS:%{http_code}
" https://server-pod.server-ns/ 2>&1 | tail -1'; else echo "no HTTP client available"; fi

